import Foundation

/// A curated dictionary entry from the bundled `dictionary.json` (generated by
/// `tools/glossary/export_dictionary.py`). `meaning` is card-sized — the sense
/// the stories use; other senses and usage live in `note`.
struct WordEntry: Decodable, Hashable {
    let meaning: String
    /// Dictionary form for inflected words (వెళ్ళాడు → వెళ్ళు).
    let base: String?
    let baseMeaning: String?
    let pos: String?
    let note: String?

    private enum CodingKeys: String, CodingKey {
        case meaning = "m", base = "b", baseMeaning = "bm", pos = "p", note = "n"
    }
}
